contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmount, uint withAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmount)); require(depAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depAmount);
        require(withAmount <= depAmount);

        uint beforeC = address(c).balance;

        c.deposit{value: depAmount}(); if (__ESBMC_reverted()) return;

        uint afterDepositC = address(c).balance;
        uint afterDepositCredit = afterDepositC - beforeC;

        bool keep = afterDepositC == beforeC + depAmount &&
                    afterDepositCredit == depAmount;

        // withdrawAll can only withdraw the test contract's credit.
        // Since the test contract is the only depositor, afterDepositCredit is its credit.
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterWithdrawC = address(c).balance;

        assert(keep &&
               !reverted &&
               afterWithdrawC == afterDepositC - afterDepositCredit);
    }

    receive() external payable {}
}

