// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depAmount, uint256 withAmount) internal {
        depAmount = bound(depAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depAmount);
        vm.assume(withAmount <= depAmount);
        uint beforeC = address(c).balance;
        try c.deposit{value: depAmount}() {} catch { return; }
        uint afterDepositC = address(c).balance;
        uint afterDepositCredit = afterDepositC - beforeC;
        bool keep = afterDepositC == beforeC + depAmount &&
                    afterDepositCredit == depAmount;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterWithdrawC = address(c).balance;
        assertTrue(keep &&
               !reverted &&
               afterWithdrawC == afterDepositC - afterDepositCredit);
    }

    function testFuzz_run(uint256 depAmount, uint256 withAmount) public {
        _run(depAmount, withAmount);
    }

    receive() external payable {}
}
